def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    freq = {}
    for row in grid:
        for v in row: freq[v] = freq.get(v, 0) + 1
    bg = max(freq, key=freq.get)
    border_colors = {grid[0][c] for c in range(w) if grid[0][c] != bg} | {grid[h-1][c] for c in range(w) if grid[h-1][c] != bg} | {grid[r][0] for r in range(h) if grid[r][0] != bg} | {grid[r][w-1] for r in range(h) if grid[r][w-1] != bg}
    border_color = max(border_colors, key=lambda v: sum(v in row for row in grid))
    targets = {grid[r][c] for r in range(h) for c in range(w) if grid[r][c] not in (bg, border_color)}
    target = next(iter(targets))
    points = [(r,c) for r in range(h) for c in range(w) if grid[r][c] == target]
    k = len(points)
    rays = []
    # Each contiguous run on an edge emits k rays from its last k cells along the edge.
    for edge, seq in [('top', [(0,c) for c in range(w)]), ('bottom', [(h-1,c) for c in range(w)]), ('left', [(r,0) for r in range(h)]), ('right', [(r,w-1) for r in range(h)])]:
        i=0
        while i < len(seq):
            if grid[seq[i][0]][seq[i][1]] != border_color:
                i+=1; continue
            j=i
            while j+1 < len(seq) and grid[seq[j+1][0]][seq[j+1][1]] == border_color: j+=1
            run=seq[i:j+1]
            for r,c in run[-k:]: rays.append((edge,r,c))
            i=j+1
    for edge,r,c in rays:
        dr,dc = {'top':(1,0),'bottom':(-1,0),'left':(0,1),'right':(0,-1)}[edge]
        rr,cc=r+dr,c+dc
        while 0 <= rr < h and 0 <= cc < w:
            v=grid[rr][cc]
            if v == target:
                out[rr][cc]=4
                break
            # Ray colors empty background cells, but never overwrites another boundary stripe.
            if v == bg:
                out[rr][cc]=target
            rr += dr; cc += dc
    return out

