program_source='''from collections import Counter


def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    counts = Counter(v for row in grid for v in row)
    background = counts.most_common(1)[0][0]

    edges = [
        ("top", [(0, c) for c in range(w)], (1, 0)),
        ("bottom", [(h - 1, c) for c in range(w)], (-1, 0)),
        ("left", [(r, 0) for r in range(h)], (0, 1)),
        ("right", [(r, w - 1) for r in range(h)], (0, -1)),
    ]

    border_colors = set()
    for _, cells, _ in edges:
        i = 0
        while i < len(cells):
            r, c = cells[i]
            color = grid[r][c]
            j = i
            while j + 1 < len(cells) and grid[cells[j + 1][0]][cells[j + 1][1]] == color:
                j += 1
            if color != background and j - i + 1 > 1:
                border_colors.add(color)
            i = j + 1

    border = max(border_colors, key=lambda color: sum(color in row for row in grid))
    target = next(color for color in counts if color not in (background, border))
    target_points = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == target]

    runs_by_axis = {"horizontal": [], "vertical": []}
    for edge, cells, direction in edges:
        i = 0
        while i < len(cells):
            r, c = cells[i]
            if grid[r][c] != border:
                i += 1
                continue
            j = i
            while j + 1 < len(cells) and grid[cells[j + 1][0]][cells[j + 1][1]] == border:
                j += 1
            run = cells[i:j + 1]
            if len(run) > 1:
                axis = "horizontal" if edge in ("top", "bottom") else "vertical"
                runs_by_axis[axis].append((edge, run, direction))
            i = j + 1

    active_runs = []
    for axis, runs in runs_by_axis.items():
        matched_masks = {}
        for idx, (edge, run, (dr, dc)) in enumerate(runs):
            mask = set()
            for offset, (r, c) in enumerate(run):
                rr, cc = r + dr, c + dc
                while 0 <= rr < h and 0 <= cc < w:
                    if grid[rr][cc] == target:
                        mask.add(offset)
                        break
                    rr += dr
                    cc += dc
            if mask:
                matched_masks.setdefault(len(run), []).append(mask)

        for edge, run, direction in runs:
            mask = set()
            # Use target-aligned lanes when present; otherwise copy the aligned
            # lane pattern from a same-length border run on the opposite edge.
            for (other_edge, other_run, (dr, dc)) in runs:
                if len(other_run) != len(run):
                    continue
                candidate = set()
                for offset, (r, c) in enumerate(other_run):
                    rr, cc = r + dr, c + dc
                    while 0 <= rr < h and 0 <= cc < w:
                        if grid[rr][cc] == target:
                            candidate.add(offset)
                            break
                        rr += dr
                        cc += dc
                if other_edge == edge and candidate:
                    mask = candidate
                    break
                if candidate and not mask:
                    mask = candidate
            if not mask:
                k = len(target_points)
                mask = set(range(max(0, len(run) - k), len(run)))
            active_runs.append((run, direction, mask))

    for run, (dr, dc), mask in active_runs:
        for offset in mask:
            r, c = run[offset]
            rr, cc = r + dr, c + dc
            while 0 <= rr < h and 0 <= cc < w:
                if grid[rr][cc] == target:
                    out[rr][cc] = 4
                    break
                if grid[rr][cc] == background:
                    out[rr][cc] = target
                rr += dr
                cc += dc

    return out
